package com.student.studentanalyzer.config; import com.student.studentanalyzer.entity.Skill; import com.student.studentanalyzer.entity.RoleSkillRequirement; import com.student.studentanalyzer.repository.SkillRepository; import com.student.studentanalyzer.repository.RoleSkillRequirementRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; @Configuration public class DataInitializer { @Bean public CommandLineRunner loadSampleSkills( SkillRepository skillRepository, RoleSkillRequirementRepository requirementRepository) { return args -> { addSkill(skillRepository, "Java", "Object-oriented programming language", "Programming", 8); addSkill(skillRepository, "Python", "Programming language used in development and AI", "Programming", 8); addSkill(skillRepository, "SQL", "Language used to manage databases", "Database", 7); addSkill(skillRepository, "React", "JavaScript library used to build user interfaces", "Frontend", 7); addSkill(skillRepository, "Spring Boot", "Java framework used to build backend applications", "Backend", 8); addSkill(skillRepository, "Data Structures and Algorithms", "Problem-solving using data structures and algorithms", "Computer Science", 9); addSkill(skillRepository, "HTML", "Markup language used to create web pages", "Frontend", 6); addSkill(skillRepository, "CSS", "Language used to style web pages", "Frontend", 6); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "HTML", 9); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "CSS", 9); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "React", 9); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "Java", 2); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "Python", 2); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "SQL", 6); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "Spring Boot", 2); addRequirement(requirementRepository, skillRepository, "Frontend Developer", "Data Structures and Algorithms", 7); addRequirement(requirementRepository, skillRepository, "Python Developer", "Python", 10); addRequirement(requirementRepository, skillRepository, "Python Developer", "SQL", 8); addRequirement(requirementRepository, skillRepository, "Python Developer", "Data Structures and Algorithms", 8); addRequirement(requirementRepository, skillRepository, "Python Developer", "Java", 3); addRequirement(requirementRepository, skillRepository, "Python Developer", "React", 3); addRequirement(requirementRepository, skillRepository, "Python Developer", "Spring Boot", 2); addRequirement(requirementRepository, skillRepository, "Python Developer", "HTML", 4); addRequirement(requirementRepository, skillRepository, "Python Developer", "CSS", 4); addRequirement(requirementRepository, skillRepository, "Java Developer", "Java", 10); addRequirement(requirementRepository, skillRepository, "Java Developer", "Spring Boot", 9); addRequirement(requirementRepository, skillRepository, "Java Developer", "SQL", 8); addRequirement(requirementRepository, skillRepository, "Java Developer", "Data Structures and Algorithms", 9); addRequirement(requirementRepository, skillRepository, "Java Developer", "Python", 3); addRequirement(requirementRepository, skillRepository, "Java Developer", "React", 4); addRequirement(requirementRepository, skillRepository, "Java Developer", "HTML", 4); addRequirement(requirementRepository, skillRepository, "Java Developer", "CSS", 4); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "Java", 8); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "Python", 6); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "SQL", 8); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "React", 9); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "Spring Boot", 9); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "Data Structures and Algorithms", 8); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "HTML", 9); addRequirement(requirementRepository, skillRepository, "Full Stack Developer", "CSS", 9); addRequirement(requirementRepository, skillRepository, "Data Analyst", "Python", 8); addRequirement(requirementRepository, skillRepository, "Data Analyst", "SQL", 10); addRequirement(requirementRepository, skillRepository, "Data Analyst", "Data Structures and Algorithms", 6); addRequirement(requirementRepository, skillRepository, "Data Analyst", "Java", 3); addRequirement(requirementRepository, skillRepository, "Data Analyst", "React", 2); addRequirement(requirementRepository, skillRepository, "Data Analyst", "Spring Boot", 2); addRequirement(requirementRepository, skillRepository, "Data Analyst", "HTML", 3); addRequirement(requirementRepository, skillRepository, "Data Analyst", "CSS", 3); System.out.println("Skills and role requirements initialized!"); }; } private void addSkill( SkillRepository skillRepository, String name, String description, String category, int requiredLevel) { Skill skill = skillRepository.findAll() .stream() .filter(s -> s.getName().equalsIgnoreCase(name)) .findFirst() .orElse(null); if (skill == null) { skill = new Skill(); skill.setName(name); skill.setDescription(description); skill.setCategory(category); skill.setRequiredLevel(requiredLevel); skillRepository.save(skill); System.out.println("Added skill: " + name); } } private void addRequirement( RoleSkillRequirementRepository requirementRepository, SkillRepository skillRepository, String roleName, String skillName, int requiredLevel) { boolean exists = requirementRepository .findByRoleNameIgnoreCase(roleName) .stream() .anyMatch(r -> r.getSkill().getName() .equalsIgnoreCase(skillName)); if (!exists) { Skill skill = skillRepository.findAll() .stream() .filter(s -> s.getName() .equalsIgnoreCase(skillName)) .findFirst() .orElseThrow(() -> new RuntimeException("Skill not found: " + skillName)); RoleSkillRequirement requirement = new RoleSkillRequirement(); requirement.setRoleName(roleName); requirement.setSkill(skill); requirement.setRequiredLevel(requiredLevel); requirementRepository.save(requirement); } } }